using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        _reportingConfiguration = new ReportingConfiguration(
            evaluators,
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-results"));
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(nameof(GreetingResponse_IsCoherentAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassMinimumScore(3);
    }

    [TestMethod]
    public async Task SummarizationResponse_IsGrounded()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(nameof(SummarizationResponse_IsGrounded));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User,
                "Summarize the following: The .NET platform is a free, cross-platform, open source developer platform for building many kinds of applications.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassMinimumScore(3);
    }
}

